private string GetCheckingCodeInput()
{
    if (!string.IsNullOrWhiteSpace(lookupCheckingCode.EditValueText))
        return lookupCheckingCode.EditValueText.Trim();
    if (!string.IsNullOrWhiteSpace(lookupCheckingCode.EditValueString))
        return lookupCheckingCode.EditValueString.Trim();
    return "";
}

private void ApplyCheckingHeaderFromRow(DataRow row)
{
    if (row == null)
        return;
    txtCheckingName.Text = Convert.ToString(row[FAM_DeviceChecking.C_CheckingName]);
    uOffice.EditValueInt32 = row[FAM_DeviceChecking.C_OfficeID] == DBNull.Value ? (int?)null : Convert.ToInt32(row[FAM_DeviceChecking.C_OfficeID]);
    lookupPlaceID.EditValueInt32 = row[FAM_DeviceChecking.C_PlaceID] == DBNull.Value ? (int?)null : Convert.ToInt32(row[FAM_DeviceChecking.C_PlaceID]);
    if (row[FAM_DeviceChecking.C_YearID] != DBNull.Value)
        txtYearKK.EditValue = Convert.ToInt32(row[FAM_DeviceChecking.C_YearID]);
    if (row[FAM_DeviceChecking.C_PeriodType] != DBNull.Value)
    {
        int periodType = Convert.ToInt32(row[FAM_DeviceChecking.C_PeriodType]);
        cboPeriodType.SelectedIndex = periodType - 1;
        if (periodType == 2 && row[FAM_DeviceChecking.C_QuarterNo] != DBNull.Value)
            cboQuarter.SelectedIndex = Convert.ToInt32(row[FAM_DeviceChecking.C_QuarterNo]) - 1;
    }
}

private void lookupCheckingCode_EditValueChanged(object sender, EventArgs e)
{
    if (bolSkipCheckingLookupChanged || !lookupCheckingCode.EditValueInt64.HasValue)
        return;
    DataTable table = FAM_DeviceCheckingService.Table;
    if (table == null)
        return;
    DataRow[] rows = table.Select(FAM_DeviceChecking.C_DeviceCheckingID + "=" + Convert.ToString(lookupCheckingCode.EditValueInt64.Value));
    if (rows.Length == 0)
        return;
    bolSkipCheckingLookupChanged = true;
    try
    {
        ApplyCheckingHeaderFromRow(rows[0]);
    }
    finally
    {
        bolSkipCheckingLookupChanged = false;
    }
    LoadCheckingDetail(lookupCheckingCode.EditValueInt64.Value);
}

