using System;
using System.Windows.Forms;
using Global;
using Libs;
using FamObject;
using FamService;
using GeneralService;

namespace FamManager.Device
{
    public partial class frmDeviceCheckingCreate : FormBase
    {
        public long? CreatedDeviceCheckingID { get; private set; }
        public bool IsOk { get; private set; }

        public frmDeviceCheckingCreate()
        {
            InitializeComponent();
        }

        public void SetDefaults(int? officeID, int? placeID)
        {
            uOffice.EditValueInt32 = officeID;
            lookupPlaceID.EditValueInt32 = placeID;
            txtYearKK.EditValue = DateTime.Today.Year;
            if (cboPeriodType.SelectedIndex < 0)
                cboPeriodType.SelectedIndex = 0;
            cboQuarter.Enabled = cboPeriodType.SelectedIndex == 1;
        }

        private void frmDeviceCheckingCreate_Load(object sender, EventArgs e)
        {
            IsOk = false;
            CreatedDeviceCheckingID = null;
            uOffice.InitData();
            GEN_PlaceService.InitLookUpEdit(lookupPlaceID);
            if (cboPeriodType.Items.Count > 0 && cboPeriodType.SelectedIndex < 0)
                cboPeriodType.SelectedIndex = 0;
        }

        private void cboPeriodType_SelectedIndexChanged(object sender, EventArgs e)
        {
            cboQuarter.Enabled = cboPeriodType.SelectedIndex == 1;
        }

        private void btnCancel_Click(object sender, EventArgs e)
        {
            IsOk = false;
            DialogResult = DialogResult.Cancel;
            Close();
        }

        private void btnSave_Click(object sender, EventArgs e)
        {
            string checkingCode = txtCheckingCode.TextTrim;
            string checkingName = txtCheckingName.TextTrim;
            if (string.IsNullOrWhiteSpace(checkingCode))
                checkingCode = checkingName;
            if (string.IsNullOrWhiteSpace(checkingName))
                checkingName = checkingCode;
            if (string.IsNullOrWhiteSpace(checkingCode))
            {
                MessageManager.Warning("Nhập Mã đợt hoặc Tên đợt.");
                txtCheckingCode.Focus();
                return;
            }
            if (!txtYearKK.EditValueInt32.HasValue || txtYearKK.EditValueInt32.Value < 2000)
            {
                MessageManager.Warning("Năm kiểm kê không hợp lệ.");
                return;
            }
            int periodType = cboPeriodType.SelectedIndex + 1;
            int quarterNo = periodType == 1 ? 0 : cboQuarter.SelectedIndex + 1;
            if (periodType == 2 && quarterNo < 1)
            {
                MessageManager.Warning("Vui lòng chọn quý kiểm kê.");
                return;
            }
            FAM_DeviceChecking obj = new FAM_DeviceChecking();
            obj.CheckingCode = checkingCode;
            obj.CheckingName = checkingName;
            obj.OfficeID = uOffice.EditValueInt32;
            obj.PlaceID = lookupPlaceID.EditValueInt32;
            obj.YearID = txtYearKK.EditValueInt32.Value;
            obj.PeriodType = periodType;
            obj.QuarterNo = quarterNo;
            obj.CheckingDate = DateTime.Today;
            obj.CreatedUser = UserSession.Username;
            if (!obj.Add())
            {
                ErrorManager.Error("Không tạo được đợt kiểm kê. " + (obj.ErrorException == null ? "" : obj.ErrorException.Message));
                return;
            }
            CreatedDeviceCheckingID = obj.DeviceCheckingID;
            IsOk = true;
            FAM_DeviceCheckingService.HaveNewData = true;
            DialogResult = DialogResult.OK;
            Close();
        }
    }
}

