private static bool IsLookupPlaceholder(string value)
{
    if (string.IsNullOrWhiteSpace(value))
        return true;
    value = value.Trim();
    return value.StartsWith("--", StringComparison.Ordinal);
}

private string GetCheckingCodeInput()
{
    string code = "";
    if (!string.IsNullOrWhiteSpace(lookupCheckingCode.EditValueText))
        code = lookupCheckingCode.EditValueText.Trim();
    else if (!string.IsNullOrWhiteSpace(lookupCheckingCode.EditValueString))
        code = lookupCheckingCode.EditValueString.Trim();
    if (IsLookupPlaceholder(code))
        return "";
    return code;
}

/// <summary>
/// Tạo mới: mã ở lookup hoặc ô tên; tên trống thì dùng luôn mã.
/// </summary>
private bool TryResolveNewCheckingInputs(out string checkingCode, out string checkingName)
{
    checkingCode = GetCheckingCodeInput();
    checkingName = txtCheckingName.TextTrim;
    if (string.IsNullOrWhiteSpace(checkingCode))
        checkingCode = checkingName;
    if (string.IsNullOrWhiteSpace(checkingName))
        checkingName = checkingCode;
    if (string.IsNullOrWhiteSpace(checkingCode))
    {
        MessageManager.Warning("Bước 1: nhập Mã đợt, hoặc chỉ nhập Tên (hệ thống lấy làm mã).");
        return false;
    }
    return true;
}

