{
    if (!bolIsExistIData)
        objIData = DCore.Data.CreateData();
    try
    {
        objIData.CreateNewStoredProcedure("FAM_DeviceChecking_Update");
        objIData.AddParameter(P_DeviceCheckingID, lngDeviceCheckingID);
        objIData.AddParameter(P_CheckingCode, strCheckingCode);
        objIData.AddParameter(P_CheckingName, strCheckingName);
        objIData.AddParameter(P_OfficeID, intOfficeID);
        objIData.AddParameter(P_PlaceID, intPlaceID);
        objIData.AddParameter(P_YearID, intYearID);
