        objIData.AddParameter(P_CheckingDate, dtmCheckingDate);
        objIData.AddParameter(P_ResponsibleEmployeeID, intResponsibleEmployeeID);
        objIData.AddParameter(P_Description, strDescription);
        objIData.AddParameter(P_UpdatedUser, strUpdatedUser);
