                return null;
            return Convert.ToInt64(row[FAM_DeviceChecking.C_DeviceCheckingID]);
        }

        private int GetFocusedStatusID()
        {
            DataRow row = GetFocusedRow();
            if (row == null || row[FAM_DeviceChecking.C_StatusID] == DBNull.Value)
                return 0;
