        private void btnDelete_Click(object sender, EventArgs e)
        {
            long? id = GetFocusedCheckingID();
            if (!id.HasValue)
                return;
            if (MessageManager.Confirm("Xóa đợt kiểm kê đang chọn?") != DialogResult.Yes)
                return;
            FAM_DeviceChecking obj = new FAM_DeviceChecking();
            if (!obj.Delete(id.Value, UserSession.Username))
            {
                ErrorManager.Error("Không xóa được. " + (obj.ErrorException == null ? "" : obj.ErrorException.Message));
                return;
            }
            FAM_DeviceCheckingService.HaveNewData = true;
            new Thread(LoadData).Start();
        }

        private void btnComplete_Click(object sender, EventArgs e)
        {
            long? id = GetFocusedCheckingID();
            if (!id.HasValue)
                return;
            if (MessageManager.Confirm("Hoàn tất và khóa đợt kiểm kê này?") != DialogResult.Yes)
